// Skis standing tips-up facing the camera with both poles planted in front of them.
function standingSet(c){const L=c.skiLength/100,P=c.poleLength/100,t=3,sx=Math.sin(t*D)*P/2,cy=Math.cos(t*D)*P/2+.003;return [[-.032,L/2+.004,-.09,-90,0,180],[.032,L/2+.004,-.09,-90,0,180],[-.07-sx,cy,.05,-90,-t,0],[.07+sx,cy,.05,-90,t,0]];}
// Skis lying flat side by side, poles alongside.
function flatSet(){return [[-.045,0,0,0,0,0],[.045,0,0,0,0,0],[-.3,0,-.12,0,4,0],[.32,0,-.1,0,-6,0]];}
