function toast(message,action){const t=$('toast'),b=$('toastAction');$('toastText').textContent=message;b.hidden=!action;b.onclick=null;if(action){b.textContent=action.label;b.onclick=()=>{t.classList.remove('show');action.run();};}t.classList.toggle('has-action',!!action);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),action?6000:3500);}
