  scene.add(new THREE.HemisphereLight('#ffffff','#c2c6cd',.8));const key=new THREE.DirectionalLight('#fff7ec',2);key.position.set(-1.6,3.5,2);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-3,right:3,top:3,bottom:-3,near:.05,far:12});key.shadow.normalBias=.002;key.shadow.bias=-.0001;key.shadow.radius=4;scene.add(key);const fill=new THREE.DirectionalLight('#eef4ff',.75);fill.position.set(2,1.5,-1);scene.add(fill);
  ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.ShadowMaterial({opacity:.17,depthWrite:false}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);groundGuide=new GroundGuide();scene.add(groundGuide);grid=new THREE.GridHelper(6,60,'#b3bdcc','#dbe1ea');grid.material.transparent=true;grid.material.opacity=.45;grid.visible=false;scene.add(grid);
  root=new THREE.Group();scene.add(root);pivot=new THREE.Group();root.add(pivot);for(let i=0;i<4;i++){const o=i<2?createSki(config):createPole(config,i===2?-1:1);o.userData={...o.userData,id:i,side:i===2?-1:1};root.add(o);gear.push(o);}human=new HumanRig();root.add(human);items=[...gear,human];attachments=new AttachmentSystem(gear,human,config,settings);
  gizmo=new TransformControls(camera,renderer.domElement);gizmo.setSize(.72);gizmoHelper=gizmo.getHelper();scene.add(gizmoHelper);gizmo.addEventListener('dragging-changed',e=>orbit.enabled=!e.value);gizmo.addEventListener('objectChange',processTransform);gizmo.addEventListener('mouseUp',()=>{markDirty();record();});
  renderUI();bindUI();bindUX();resize();applyPreset('parallel',false);select([0]);loadLibrary();const saved=readStorage(STORE);if(saved){try{restore(saved.scene||saved);activePresetId=library.some(e=>e.id===saved.presetId)?saved.presetId:null;}catch{toast('Сохранённая сцена не открылась. Вы можете импортировать резервный JSON.');}}else fit(false);renderLibrary();record();showLibrary(human.visible?'poses':'layouts');
