function updateHint(){const el=$('contextHint');if(!el)return;const rotate=state.mode==='rotate';if(matchMedia('(pointer: coarse)').matches){el.textContent=state.rigPart?(rotate?'Вращайте кольца в кадре':'Тяните цветную точку'):state.selected.length?(rotate?'Тяните кольца, чтобы повернуть':'Тяните стрелки, чтобы сдвинуть'):'Коснитесь предмета, чтобы выбрать · Двумя пальцами — масштаб';return;}el.textContent=state.rigPart?(rotate?'Вращайте кольца в кадре · ← → — поворот на 5°, с Shift — 15°':'Тяните цветную точку · ← ↑ ↓ → — сдвиг на 1 см, с Shift — 10 см'):state.selected.length?(rotate?'Тяните кольца · ← → — поворот на 5°, с Shift — 15° · G — двигать':'Тяните стрелки · ← ↑ ↓ → — сдвиг на 1 см, с Shift — 10 см · R — вращать'):'Кликните лыжу, палку или человека · Левая кнопка — крутить · Правая — сдвиг · Колесо — масштаб';}
function hideSelection(){const ids=state.selected.filter(i=>items[i]?.visible);if(!ids.length||state.rigPart)return;ids.forEach(i=>{items[i].visible=false;});if(ids.includes(4))document.querySelector('.objects-section').open=true;select([]);syncRig();updateObjectList();record();toast(ids.length===1?`Скрыто: ${itemNames[ids[0]]}`:`Скрыто объектов: ${ids.length}`,undoAction);}
function bindUX(){
  $('frameBtn').onclick=()=>setTab('export');
  // First-visit coach card.
  const coach=$('coach'),COACH='ski-form-onboarded-v1',hideCoach=()=>{coach.hidden=true;try{localStorage.setItem(COACH,'1');}catch{}};
  try{coach.hidden=!!localStorage.getItem(COACH);}catch{coach.hidden=true;}
  $('coachDone').onclick=$('coachClose').onclick=hideCoach;$('coachHelp').onclick=()=>{hideCoach();$('helpDialog').showModal();};
  // Drag an X/Y/Z label to scrub its value; Shift ×10, Alt ×0.1.
  document.addEventListener('pointerdown',e=>{const label=e.target.closest('.axis-field>span'),input=label?.parentElement.querySelector('input');if(!input||input.disabled||e.button!==0)return;e.preventDefault();const rot=input.id.includes('rot');let last=e.clientX,value=parseFloat(input.value)||0,moved=false;label.setPointerCapture(e.pointerId);document.body.classList.add('scrubbing');
    const move=ev=>{const dx=ev.clientX-last;if(!dx)return;last=ev.clientX;moved=true;value+=dx*(rot?1:.5)*(ev.shiftKey?10:1)*(ev.altKey?.1:1);input.value=Math.round(value*10)/10;input.dispatchEvent(new Event('input'));};
    const up=()=>{label.removeEventListener('pointermove',move);label.removeEventListener('pointerup',up);label.removeEventListener('pointercancel',up);document.body.classList.remove('scrubbing');if(moved)input.dispatchEvent(new Event('change'));else{input.focus();input.select();}};
    label.addEventListener('pointermove',move);label.addEventListener('pointerup',up);label.addEventListener('pointercancel',up);});
  // Arrow keys nudge the selection in the direction it appears on screen.
  const q=new THREE.Quaternion(),keys={ArrowLeft:[-1,0,0],ArrowRight:[1,0,0],ArrowUp:[0,1,0],ArrowDown:[0,-1,0],PageUp:[0,0,1],PageDown:[0,0,-1]};
  document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='?'){e.preventDefault();$('helpDialog').showModal();return;}
    const a=keys[e.key];if(!a||e.ctrlKey||e.metaKey||e.altKey)return;const o=selectedObject();if(!o)return;e.preventDefault();
    if(state.mode==='rotate'){if(!a[0])return;o.rotateOnWorldAxis(new THREE.Vector3(0,1,0),-a[0]*(e.shiftKey?15:5)*D);}
    else{const delta=new THREE.Vector3();if(a[2])delta.y=a[2];else{camera.updateMatrixWorld();const dir=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,a[0]?0:1).multiplyScalar(a[0]||a[1]);if(!a[0]&&Math.abs(dir.y)>.7)delta.y=Math.sign(dir.y);else if(Math.abs(dir.x)>=Math.abs(dir.z))delta.x=Math.sign(dir.x);else delta.z=Math.sign(dir.z);}
      delta.multiplyScalar((e.shiftKey?10:1)/100);if(o.parent){o.parent.getWorldQuaternion(q);delta.applyQuaternion(q.invert());}o.position.add(delta);}
    o.updateMatrixWorld(true);processTransform();markDirty();clearTimeout(nudgeTimer);nudgeTimer=setTimeout(()=>{nudgeTimer=null;record();},350);});
  if(/Mac|iPhone|iPad/.test(navigator.platform)){document.querySelectorAll('kbd.k').forEach(k=>{if(k.textContent==='Ctrl')k.textContent='⌘';});for(const id of ['undoBtn','redoBtn','saveBtn'])$(id).title=$(id).title.replace(/Ctrl/g,'⌘');}
}
function restore(raw){const data=upgradeScene(raw),selection=[...state.selected],rigPart=state.rigPart;state.restoring=true;try{releaseSelection();state.selected=[];state.rigPart=null;for(const key of Object.keys(defaults))config[key]=key in data.config?data.config[key]:defaults[key];for(const key of Object.keys(DEFAULT_SETTINGS))settings[key]=data.settings[key];gear.forEach((o,i)=>{replaceModel(o,config);o.position.fromArray(data.objects[i].position);o.quaternion.fromArray(data.objects[i].quaternion).normalize();o.visible=data.objects[i].visible;});human.state=clone(data.human.state);human.visible=data.human.visible;document.querySelector('.objects-section').open=!human.visible;human.initialized=data.human.initialized;human.position.fromArray(data.human.position);human.quaternion.fromArray(data.human.quaternion).normalize();attachments.links=clone(data.links);human.update();attachments.follow();projection(settings.projection,false);camera.position.fromArray(data.camera.position);camera.quaternion.fromArray(data.camera.quaternion).normalize();camera.zoom=data.camera.zoom;orbit.target.fromArray(data.camera.target);if(camera.isPerspectiveCamera)camera.setFocalLength(settings.focal);camera.updateProjectionMatrix();orbit.update();state.label=cleanName(data.label);state.poseId=typeof data.poseId==='string'?data.poseId:'stand';$('compositionLabel').textContent=state.label;applySettings();resize();clearActivePresets();if(rigPart&&human.visible)selectRig(rigPart);else select(selection);updateLibraryStatus();}finally{state.restoring=false;}}

function download(blob,name,{file=false}={}){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();if(file){if(lastFileURL)URL.revokeObjectURL(lastFileURL);lastFileURL=url;const link=$('lastJSONLink');link.href=url;link.download=name;link.hidden=false;}else setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportPNG(){if(exporting)return;exporting=true;$('exportTop').disabled=$('exportBtn').disabled=true;const [w,h]=exportDimensions(),ratio=renderer.getPixelRatio(),visibility={grid:grid.visible,floor:groundGuide.visible,gizmo:gizmoHelper.visible,rig:human.helpers.visible,outlines:outlines.map(l=>l.visible)};try{toast(`Готовим PNG ${w} × ${h}…`);await new Promise(r=>requestAnimationFrame(r));orbit.update();grid.visible=false;groundGuide.visible=settings.floorEnabled&&settings.floorExport;gizmoHelper.visible=false;human.helpers.visible=false;outlines.forEach(l=>l.visible=false);renderer.setPixelRatio(1);renderer.setSize(w,h,false);camera.aspect=w/h;if(camera.isOrthographicCamera){camera.left=-w/h;camera.right=w/h;}camera.updateProjectionMatrix();renderer.render(scene,camera);const blob=await new Promise((resolve,reject)=>renderer.domElement.toBlob(b=>b?resolve(b):reject(Error('PNG не создан')),'image/png')),dataURL=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);}),name=`ski-form-${w}x${h}-${Date.now()}.png`;$('exportPreview').src=dataURL;$('exportAgain').href=dataURL;$('exportAgain').download=name;$('exportResultSize').textContent=`${w} × ${h} · PNG`;$('exportResult').hidden=false;download(blob,name);toast('PNG готов и скачан',{label:'Показать',run:()=>setTab('export')});}catch(error){console.error(error);toast('Не удалось выгрузить PNG. Попробуйте меньшее разрешение.');}finally{renderer.setPixelRatio(ratio);grid.visible=visibility.grid;groundGuide.visible=visibility.floor;gizmoHelper.visible=visibility.gizmo;human.helpers.visible=visibility.rig;outlines.forEach((l,i)=>l.visible=visibility.outlines[i]);exporting=false;resize();renderer.render(scene,camera);$('exportTop').disabled=$('exportBtn').disabled=false;}}
function exportEntry(entry){download(new Blob([JSON.stringify({format:'ski-form-scene',version:1,name:entry.name,scene:entry.scene},null,2)],{type:'application/json'}),`ski-form-${Date.now()}.json`,{file:true});toast('JSON готов. Его можно отправить и открыть в другой студии Ski Form.');}
function saveFile(){exportEntry({name:state.label,scene:sceneData()});}
function exportLibrary(){if(!library.length){toast('Сначала сохраните хотя бы один пресет');return;}download(new Blob([JSON.stringify({format:'ski-form-library',version:1,presets:library.map(({name,scene})=>({name,scene}))},null,2)],{type:'application/json'}),`ski-form-library-${Date.now()}.json`,{file:true});toast(`Библиотека из ${library.length} пресетов готова`);}
function loadLibrary(){const stored=readStorage(LIBRARY);if(!Array.isArray(stored))return;for(const entry of stored.slice(0,500)){try{library.push({id:String(entry.id||newId()),name:cleanName(entry.name),scene:upgradeScene(entry.scene)});}catch{}}}
function writeLibrary(next){if(next.length>500){toast('В библиотеке может быть до 500 пресетов. Скачайте часть коллекции в JSON.');return false;}if(estimatedBytes(next)>LIBRARY_BUDGET){toast('Библиотека заполнена. Скачайте её и удалите ненужные пресеты.');return false;}if(!writeStorage(LIBRARY,next)){toast('Не удалось сохранить библиотеку. Скачайте резервный JSON.');return false;}library=next;renderLibrary();return true;}
function updateLibraryStatus(){const entry=library.find(e=>e.id===activePresetId);$('updatePreset').disabled=!entry;$('updatePreset').textContent=entry?'Обновить открытый пресет':'Обновить текущий пресет';$('activePresetLabel').textContent=entry?`Открыт: ${entry.name}${physicalSignature(sceneData())!==physicalSignature(entry.scene)?' · есть изменения':''}`:'Откройте пресет, чтобы обновить его.';$('libraryCount').textContent=library.length;const size=estimatedBytes(library);$('storageMeter').value=size;$('storageLabel').textContent=`${library.length} пресетов · ${Math.ceil(size/1024)} КБ из 3584 КБ`;$('exportLibrary').disabled=!library.length;}
function renderLibrary(){const host=$('savedPresets');host.replaceChildren();const query=$('presetSearch').value.trim().toLowerCase(),filtered=library.filter(e=>e.name.toLowerCase().includes(query));if(!filtered.length){const empty=document.createElement('div');empty.className='saved-empty';empty.textContent=library.length?'Ничего не найдено':'Соберите постановку и нажмите «Сохранить новый пресет».';host.append(empty);}for(const entry of filtered){const row=document.createElement('div');row.className='saved-row'+(entry.id===activePresetId?' active':'');const b=document.createElement('button');b.className='saved-open';b.textContent=entry.name;b.onclick=()=>{activePresetId=entry.id;restore(entry.scene);record();renderLibrary();toast('Пресет открыт');};const menu=document.createElement('button');menu.className='icon-button';menu.textContent='⋯';menu.setAttribute('aria-label',`Действия: ${entry.name}`);menu.onclick=()=>{presetActionId=entry.id;$('presetDialogTitle').textContent=entry.name;$('presetDialog').showModal();};row.append(b,menu);host.append(row);}updateLibraryStatus();}
function askName(title,value){return new Promise(resolve=>{nameResolver=resolve;$('nameDialogTitle').textContent=title;$('nameInput').value=value;$('nameDialog').showModal();$('nameInput').focus();$('nameInput').select();});}
async function saveNewPreset(){showLibrary(true);const name=await askName('Сохранить новый пресет',state.label==='Своя композиция'?'Моя композиция':state.label);if(!name)return;const scene=sceneData();scene.label=name;const entry={id:newId(),name,scene};if(writeLibrary([...library,entry])){activePresetId=entry.id;state.label=name;$('compositionLabel').textContent=name;renderLibrary();record();toast('Новый пресет сохранён в этом браузере');}}
function updateCurrentPreset(){const entry=library.find(e=>e.id===activePresetId);if(!entry)return;const data=sceneData();data.label=entry.name;if(writeLibrary(library.map(e=>e.id===entry.id?{...e,scene:data}:e))){state.label=entry.name;$('compositionLabel').textContent=entry.name;record();toast('Пресет обновлён');}}
async function presetAction(action){const entry=library.find(e=>e.id===presetActionId);$('presetDialog').close();if(!entry)return;if(action==='export'){exportEntry(entry);return;}if(action==='update'){activePresetId=entry.id;updateCurrentPreset();return;}if(action==='delete'){if(writeLibrary(library.filter(e=>e.id!==entry.id))){if(activePresetId===entry.id)activePresetId=null;updateLibraryStatus();const undo=document.createElement('button');undo.className='button secondary wide';undo.textContent=`Вернуть «${entry.name}»`;undo.onclick=()=>{if(writeLibrary([...library,entry]))undo.remove();};$('myPresetsPanel').prepend(undo);toast(`Пресет «${entry.name}» удалён`,{label:'Вернуть',run:()=>{if(writeLibrary([...library,entry]))undo.remove();}});}return;}const name=await askName(action==='rename'?'Переименовать пресет':'Создать копию',action==='rename'?entry.name:entry.name+' — копия');if(!name)return;const data=clone(entry.scene);data.label=name;if(action==='rename'){if(writeLibrary(library.map(e=>e.id===entry.id?{...e,name,scene:data}:e))&&activePresetId===entry.id){state.label=name;$('compositionLabel').textContent=name;queueSave();}}else{const copied={id:newId(),name,scene:data};if(writeLibrary([...library,copied])){activePresetId=copied.id;restore(data);record();renderLibrary();}}}
function addEntries(entries){const used=new Set(library.map(e=>e.name)),added=entries.map(e=>{const base=cleanName(e.name);let name=base,n=2;while(used.has(name))name=base.slice(0,72)+` (${n++})`;used.add(name);return {id:newId(),name,scene:upgradeScene(e.scene)};});return writeLibrary([...library,...added])?added:[];}
async function importFile(e){const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('Файл больше 5 МБ. Выберите JSON сцены или библиотеки.');return;}try{const unpacked=unpackFile(JSON.parse(await file.text())),added=addEntries(unpacked.entries);if(!added.length)return;showLibrary(true);if(!unpacked.library){activePresetId=added[0].id;restore(added[0].scene);record();renderLibrary();}toast(unpacked.library?`Добавлено пресетов: ${added.length}`:'Сцена добавлена в «Мои пресеты» и открыта');}catch(error){toast(error.message||'Не удалось импортировать файл');}}
async function shareScene(){$('shareBtn').disabled=true;try{const encoded=await encodeSharedScene(sceneData(),state.label);$('shareLink').value=location.origin+location.pathname+'#scene='+encoded;$('shareDialog').showModal();}catch{toast('Не удалось создать ссылку. Поделитесь JSON файлом.');}finally{$('shareBtn').disabled=false;}}
async function readSharedLink(){if(!location.hash.startsWith('#scene='))return;try{incoming=await decodeSharedScene(location.hash.slice(7));$('incomingName').textContent=incoming.name;$('incomingDialog').showModal();}catch(error){toast(error.message||'Не удалось открыть ссылку');clearShareHash();}}
function clearShareHash(){window.history.replaceState(null,'',location.pathname+location.search);incoming=null;}

init().catch(error=>{console.error(error);$('loading').innerHTML='<strong>3D сцена не запустилась.</strong><span>Попробуйте обновить страницу в браузере с WebGL.</span>';});
